begin;
create function pg_temp.u(p text) returns uuid language sql as $$select ('00000000-0000-0000-0000-'||lpad(p,12,'0'))::uuid$$;
insert into auth.users(id,email,email_confirmed_at) select pg_temp.u(v),v||'@example.test',now() from unnest(array['b1','c1','1','2']) v;
insert into public.profiles(id,first_name,last_name) select pg_temp.u(v),'Nome','Cognome' from unnest(array['b1','c1','1','2']) v;
insert into public.user_roles values(pg_temp.u('b1'),'board'),(pg_temp.u('c1'),'coach');
insert into public.group_members(group_id,user_id) select id,pg_temp.u('1') from public.groups where code='A';
insert into public.group_members(group_id,user_id) select id,pg_temp.u('2') from public.groups where code='B';
insert into public.rinks(id,name) overriding system value values(90,'Grande test');
update public.club_settings set home_rink_id=90;
select test.login(pg_temp.u('b1'));
select test.works('board adds a source PDF', $$insert into storage.objects(bucket_id,name) values('documents','club/doc-2000000000.pdf')$$);
select test.works('board publishes PDF metadata', $$insert into public.club_documents(title,file_path,created_by) values('Regolamento','club/doc-2000000000.pdf',auth.uid())$$);
select test.logout();
update public.club_documents set id=pg_temp.u('d1') where title='Regolamento';
select test.login(pg_temp.u('b1'));
select test.works('board creates a reading request', $$insert into public.club_requests(title,action,document_id,group_ids) values('Leggere','read',pg_temp.u('d1'),array[(select id from public.groups where code='A')])$$);
select test.logout();
update public.club_requests set id=pg_temp.u('a1');
insert into public.club_requests(id,title,action,review) values(pg_temp.u('a2'),'Caricare','upload',true),(pg_temp.u('a3'),'Caricare senza verifica','upload',false);

select test.login(pg_temp.u('1'));
select test.rows('player sees applicable requests', 'select * from public.club_requests',3);
select test.fails('player cannot create requests', $$insert into public.club_requests(title,action) values('No','upload')$$,'row-level security');
select test.fails('player cannot alter published content', $$update public.club_requests set title='Changed'$$,'permission denied');
select test.affected('player cannot archive', $$update public.club_requests set active=false$$,0);
select test.works('player confirms reading', $$select public.submit_club_request(pg_temp.u('a1'))$$);
select test.rows('confirmation has server time and current user', $$select * from public.club_request_responses where user_id=auth.uid() and submitted_at=now() and status='complete'$$,1);
select test.fails('completed confirmation is immutable', $$select public.submit_club_request(pg_temp.u('a1'))$$,'request_already_sent');
select test.fails('cannot fabricate response status', $$insert into public.club_request_responses(request_id,user_id,status) values(pg_temp.u('a2'),auth.uid(),'approved')$$,'permission denied');
select test.fails('cannot submit someone else file', $$select public.submit_club_request(pg_temp.u('a2'),pg_temp.u('2')::text||'/request-'||pg_temp.u('a2')::text||'-abcd.pdf')$$,'request_file_required');
select test.fails('upload must exist', $$select public.submit_club_request(pg_temp.u('a2'),auth.uid()::text||'/request-'||pg_temp.u('a2')::text||'-abcd.pdf')$$,'request_file_required');
select test.works('upload a personal document', $$insert into storage.objects(bucket_id,name) values('documents',auth.uid()::text||'/request-'||pg_temp.u('a2')::text||'-abcd.pdf')$$);
select test.works('submit for review', $$select public.submit_club_request(pg_temp.u('a2'),auth.uid()::text||'/request-'||pg_temp.u('a2')::text||'-abcd.pdf')$$);
select test.rows('review cannot be bypassed', $$select * from public.club_request_responses where request_id=pg_temp.u('a2') and status='pending' and reviewed_by is null$$,1);
select test.affected('submitted evidence cannot be removed', $$delete from storage.objects where name=auth.uid()::text||'/request-'||pg_temp.u('a2')::text||'-abcd.pdf'$$,0);
select test.fails('cannot replace a pending response', $$select public.submit_club_request(pg_temp.u('a2'),auth.uid()::text||'/request-'||pg_temp.u('a2')::text||'-abcd.pdf')$$,'request_already_sent');
select test.fails('player cannot approve', $$select public.review_club_request(pg_temp.u('a2'),auth.uid(),true)$$,'forbidden');
select test.login(pg_temp.u('2'));
select test.rows('other group cannot see targeted request', $$select * from public.club_requests where id=pg_temp.u('a1')$$,0);
select test.fails('other group cannot confirm', $$select public.submit_club_request(pg_temp.u('a1'))$$,'forbidden');
select test.rows('other player cannot read responses', 'select * from public.club_request_responses',0);
select test.rows('other player cannot read private upload', $$select * from storage.objects where name like '%request-%'$$,0);
select test.login(pg_temp.u('c1'));
select test.rows('staff sees all requests', 'select * from public.club_requests',3);
select test.rows('staff sees responses', 'select * from public.club_request_responses',2);
select test.fails('coach cannot publish', $$insert into public.club_requests(title,action) values('No','upload')$$,'row-level security');
select test.works('staff requests correction', $$select public.review_club_request(pg_temp.u('a2'),pg_temp.u('1'),false,'Pagina mancante')$$);
select test.rows('review records staff and note', $$select * from public.club_request_responses where status='rejected' and reviewed_by=auth.uid() and review_note='Pagina mancante'$$,1);
select test.login(pg_temp.u('1'));
select test.works('rejected upload can be resubmitted', $$select public.submit_club_request(pg_temp.u('a2'),auth.uid()::text||'/request-'||pg_temp.u('a2')::text||'-abcd.pdf')$$);
select test.rows('resubmission clears old review', $$select * from public.club_request_responses where request_id=pg_temp.u('a2') and reviewed_by is null and review_note='' and status='pending'$$,1);
select test.login(pg_temp.u('b1'));
select test.works('board approves uploaded document', $$select public.review_club_request(pg_temp.u('a2'),pg_temp.u('1'),true)$$);
select test.fails('published request is not editable by board', $$update public.club_requests set action='accept'$$,'permission denied');
select test.fails('published PDF cannot be deleted', $$delete from public.club_documents where id=pg_temp.u('d1')$$,'foreign key');
select test.affected('published evidence file cannot be deleted', $$delete from storage.objects where name='club/doc-2000000000.pdf'$$,0);
select test.affected('board archives request', $$update public.club_requests set active=false where id=pg_temp.u('a1')$$,1);
select test.login(pg_temp.u('1'));
select test.fails('archived request accepts no more responses', $$select public.submit_club_request(pg_temp.u('a1'))$$,'forbidden');
select test.login_anon();
select test.fails('anonymous cannot read requests', 'select * from public.club_requests','permission denied');
select test.fails('anonymous cannot submit', $$select public.submit_club_request(pg_temp.u('a2'))$$,'permission denied');
select test.fails('anonymous cannot review', $$select public.review_club_request(pg_temp.u('a2'),pg_temp.u('1'),true)$$,'permission denied');
select test.logout();

-- Event bookings, independent related events and display aliases.
create function pg_temp.changes(p_type text default 'game') returns jsonb language sql as $$select jsonb_build_object('type',p_type,'title','Evento test','starts_at','2030-11-12T21:30:00Z','ends_at','2030-11-12T23:00:00Z','home_away',case when p_type='game' then 'home' end,'group_ids',jsonb_build_array((select id from public.groups where code='A')),'observer_details','[]'::jsonb)$$;
select test.login(pg_temp.u('b1'));
select test.works('board sets display alias', $$update public.groups set league_alias='C Black' where code='A'$$);
select test.works('save home game with automatic rink', $$select public.save_event(null,pg_temp.changes())$$);
select test.rows('home game selects configured rink', $$select * from public.events where title='Evento test' and rink_id=90$$,1);
select test.logout();
create function pg_temp.e(p_type text) returns uuid language sql as $$select id from public.events where type::text=p_type and title='Evento test' limit 1$$;
select test.login(pg_temp.u('b1'));
select test.works('save explicit reservation', $$select public.save_event(pg_temp.e('game'),pg_temp.changes()||jsonb_build_object('rink_id',90,'booking_starts_at','2030-11-12T20:00:00Z','booking_ends_at','2030-11-12T23:30:00Z'))$$);
select test.rows('reservation is separate from game', $$select * from public.events where id=pg_temp.e('game') and booking_ends_at-booking_starts_at=interval '3 hours 30 minutes' and ends_at-starts_at=interval '90 minutes'$$,1);
select test.works('older clients retain reservation', $$select public.save_event(pg_temp.e('game'),pg_temp.changes()||jsonb_build_object('rink_id',90))$$);
select test.rows('reservation retained', $$select * from public.events where id=pg_temp.e('game') and booking_starts_at='2030-11-12T20:00:00Z'$$,1);
select test.fails('invalid reservation rolls back', $$select public.save_event(pg_temp.e('game'),pg_temp.changes()||jsonb_build_object('rink_id',90,'booking_starts_at','2030-11-12T23:30:00Z','booking_ends_at','2030-11-12T20:00:00Z'))$$,'valid_booking');
select test.logout();
update public.events set starts_at=starts_at+interval '1 hour',ends_at=ends_at+interval '1 hour' where id=pg_temp.e('game');
select test.rows('source reschedule flags existing booking', $$select * from public.events where id=pg_temp.e('game') and booking_needs_review and booking_starts_at='2030-11-12T20:00:00Z'$$,1);
select test.login(pg_temp.u('b1'));
select test.works('unrelated edits retain reservation review flag', $$select public.save_event(pg_temp.e('game'),pg_temp.changes()||jsonb_build_object('starts_at',(select starts_at from public.events where id=pg_temp.e('game')),'ends_at',(select ends_at from public.events where id=pg_temp.e('game')),'rink_id',90))$$);
select test.rows('review flag retained', $$select * from public.events where id=pg_temp.e('game') and booking_needs_review$$,1);
select test.works('staff explicitly confirms reservation', $$select public.save_event(pg_temp.e('game'),pg_temp.changes()||jsonb_build_object('starts_at',(select starts_at from public.events where id=pg_temp.e('game')),'ends_at',(select ends_at from public.events where id=pg_temp.e('game')),'rink_id',90,'booking_confirmed',true))$$);
select test.rows('explicit confirmation clears flag', $$select * from public.events where id=pg_temp.e('game') and not booking_needs_review$$,1);
select test.works('weekly training keeps each reservation at its local time', $$select public.save_event(null,pg_temp.changes('training')||jsonb_build_object('title','Serie ghiaccio','rink_id',90,'booking_starts_at','2030-11-12T20:00:00Z','booking_ends_at','2030-11-12T23:30:00Z'),'one',2)$$);
select test.rows('all occurrences have the full booking', $$select * from public.events where title='Serie ghiaccio' and booking_ends_at-booking_starts_at=interval '3 hours 30 minutes' and starts_at-booking_starts_at=interval '90 minutes'$$,3);
select test.works('create linked theory', $$select public.save_event(null,pg_temp.changes('theory')||jsonb_build_object('parent_event_id',pg_temp.e('game')))$$);
select test.works('create off ice', $$select public.save_event(null,pg_temp.changes('off_ice'))$$);
select test.works('create social event', $$select public.save_event(null,pg_temp.changes('other'))$$);
select test.logout();

select test.login(pg_temp.u('b1'));
select test.fails('cycles are refused', $$select public.save_event(pg_temp.e('game'),pg_temp.changes()||jsonb_build_object('parent_event_id',pg_temp.e('theory')))$$,'event_link_invalid');
select test.fails('cannot repeat a linked event', $$select public.save_event(null,pg_temp.changes('training')||jsonb_build_object('parent_event_id',pg_temp.e('game')),'one',2)$$,'event_link_invalid');
select test.login(pg_temp.u('1'));
select test.fails('player cannot edit booking', $$select public.save_event(pg_temp.e('game'),pg_temp.changes())$$,'forbidden');
select test.affected('player cannot set league alias', $$update public.groups set league_alias='No' where code='A'$$,0);
select test.works('player answers parent', $$select public.answer_attendance(pg_temp.e('game'),'present')$$);
select test.works('player separately answers related event', $$select public.answer_attendance(pg_temp.e('theory'),'absent')$$);
select test.rows('two independent answers', $$select * from public.attendance_answers where user_id=auth.uid()$$,2);
select test.login(pg_temp.u('b1'));
select test.works('cancel parent only', $$select public.manage_events(pg_temp.e('game'),'one','cancel',1)$$);
select test.rows('child is not cancelled', $$select * from public.events where id=pg_temp.e('theory') and cancelled_at is null$$,1);
select test.works('delete parent without deleting child', $$select public.manage_events(pg_temp.e('game'),'one','delete',1)$$);
select test.rows('child remains as independent event', $$select * from public.events where id=pg_temp.e('theory') and parent_event_id is null$$,1);
select test.logout();
rollback;
\echo 'ALL CLUB REQUEST AND BOOKING TESTS PASSED'
